& .config-detail {
  gap: var(--hub-space-medium);

  .config-protocols & {
    padding-block: 0;
  }

  & .config-item-data {
    overflow: hidden;
    display: flex;
    flex-direction: column;
    align-items: baseline;
    gap: 2px;

    & p {
      line-height: normal;
      margin: 0;

      &.title {
        text-transform: uppercase;
        color: var(--color-text-secondary);
        font-weight: 500;
        font-size: 0.8rem;
        display: inline-block;
        vertical-align: bottom;
      }

      &.data {
        color: var(--color-text-base);
        font-weight: 400;
        font-size: 1rem;
        text-wrap: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
      }
    }

    & .info {
      font-size: 0.8rem;
      line-height: 1;
    }
  }

  .config-selection & {
    gap: var(--hub-space-small);
    padding-inline-start: var(--hub-space-large);

    & .config-item-data {
      flex-wrap: nowrap;
      flex-direction: row;
      gap: var(--hub-space-small);
      inline-size: 100%;
      justify-content: flex-start;

      .config-row & {
        flex-wrap: wrap;
      }

      & .title {
        /* Ensure labels don't get truncated */
        overflow: visible;
        font-size: 0.9rem;
      }
    }
  }
}

